package net.officefloor.hq.app.claim;

import jakarta.validation.Valid;
import jakarta.validation.constraints.Digits;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.List;
import java.util.Set;
import net.officefloor.hq.app.session.SessionController;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.PutMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;
import org.springframework.web.bind.annotation.SessionAttribute;

@RestController
@Validated
@RequestMapping("/api/sheets/{sheetId}")
public class ClaimController {

    /**
     * A claim as the screen shows it; the amount always carries two decimals. The settled due is the figure fixed
     * when it was settled, or null while its due is live. Opened-by is the user who opened it, or null. Stated is
     * whether its person's last statement binds it, to the stated due (null for n/a). Corrects is the number of the
     * claim a correction corrects, or null. Rounds-on is the date its rounding follows: its own, or for a correction
     * the date of the claim it corrects. Deferred-until is the date it was deferred until, or null; it is deferred
     * while it is OPEN and the sheet's today is before that date. Log is its status log, oldest first.
     */
    public record ClaimView(Long id, Long personId, String amount, LocalDate date, String note, ClaimStatus status,
            String number, String settledDue, String openedBy, boolean stated, String statedDue, String corrects,
            LocalDate roundsOn, LocalDate dueBy, LocalDate deferredUntil, List<LogLineView> log) {
        public static ClaimView of(Claim c) {
            return new ClaimView(c.getId(), c.getPersonId(), c.getAmount().toPlainString(), c.getDate(), c.getNote(),
                    c.getStatus(), c.getNumber(), c.getSettledDue() == null ? null : c.getSettledDue().toPlainString(),
                    c.getOpenedBy(), c.isStated(), c.getStatedDue() == null ? null : c.getStatedDue().toPlainString(),
                    c.getCorrects(), c.getRoundsOn(), c.getDueBy(), c.getDeferredUntil(), c.getLog().stream().map(LogLineView::of).toList());
        }
    }

    /** A line of a claim's status log: the status, who made the change, the sheet's today then, and the due then. */
    public record LogLineView(ClaimStatus status, String by, LocalDate on, String due) {
        public static LogLineView of(ClaimLogEntry e) {
            return new LogLineView(e.getStatus(), e.getBy(), e.getOn(),
                    e.getDue() == null ? null : e.getDue().toPlainString());
        }
    }

    /**
     * A claim's fields as the form submits them; a missing date takes the sheet's today. A negative amount is a
     * correction, and corrects names the number of the settled claim it corrects.
     */
    public record ClaimForm(@NotNull @Digits(integer = 12, fraction = 2) BigDecimal amount, LocalDate date,
            @Size(max = 500) String note, @Size(max = 140) String corrects) {
    }

    /** The claims a bulk action is to change, by id. */
    public record BulkForm(@NotNull @Size(max = 1000) Set<@NotNull Long> ids) {
    }

    /** The claims a bulk open opened, in the order it numbered them, and how many it refused. */
    public record BulkOpenView(List<ClaimView> opened, int refused) {
    }

    private final ClaimService service;
    private final ClaimBulkService bulk;

    public ClaimController(ClaimService service, ClaimBulkService bulk) {
        this.service = service;
        this.bulk = bulk;
    }

    /** All the claims on the sheet, newest first. */
    @GetMapping("/claims")
    public List<ClaimView> list(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9_.-]+") String sheetId) {
        return service.list(sheetId).stream().map(ClaimView::of).toList();
    }

    @PostMapping("/people/{personId}/claims")
    public ClaimView add(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9_.-]+") String sheetId,
            @PathVariable Long personId, @Valid @RequestBody ClaimForm form,
            @SessionAttribute(SessionController.USER) String user) {
        return ClaimView.of(service.add(user, sheetId, personId, form.amount(), form.date(), form.note(),
                form.corrects()));
    }

    @PutMapping("/claims/{id}")
    public ClaimView update(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9_.-]+") String sheetId,
            @PathVariable Long id, @Valid @RequestBody ClaimForm form,
            @SessionAttribute(SessionController.USER) String user) {
        return ClaimView.of(service.update(user, sheetId, id, form.amount(), form.date(), form.note(),
                form.corrects()));
    }

    @PostMapping("/claims/{id}/open")
    public ClaimView open(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9_.-]+") String sheetId,
            @PathVariable Long id, @SessionAttribute(SessionController.USER) String user) {
        return ClaimView.of(service.changeStatus(user, sheetId, id, ClaimStatus.OPEN));
    }

    @PostMapping("/claims/bulk-open")
    public BulkOpenView bulkOpen(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9_.-]+") String sheetId,
            @Valid @RequestBody BulkForm form, @SessionAttribute(SessionController.USER) String user) {
        ClaimBulkService.Result result = bulk.open(user, sheetId, form.ids());
        return new BulkOpenView(result.changed().stream().map(ClaimView::of).toList(), result.refused());
    }

    /** The claims a bulk settle settled or made PENDING, in the order it took them, and how many it refused. */
    public record BulkSettleView(List<ClaimView> settled, int refused) {
    }

    @PostMapping("/claims/bulk-settle")
    public BulkSettleView bulkSettle(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9_.-]+") String sheetId,
            @Valid @RequestBody BulkForm form, @SessionAttribute(SessionController.USER) String user) {
        ClaimBulkService.Result result = bulk.settle(user, sheetId, form.ids());
        return new BulkSettleView(result.changed().stream().map(ClaimView::of).toList(), result.refused());
    }

    @PostMapping("/claims/{id}/settle")
    public ClaimView settle(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9_.-]+") String sheetId,
            @PathVariable Long id, @SessionAttribute(SessionController.USER) String user) {
        return ClaimView.of(service.changeStatus(user, sheetId, id, ClaimStatus.SETTLED));
    }

    @PostMapping("/claims/{id}/resettle")
    public ClaimView resettle(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9_.-]+") String sheetId,
            @PathVariable Long id, @SessionAttribute(SessionController.USER) String user) {
        return ClaimView.of(service.resettle(user, sheetId, id));
    }

    /** A steward's reason for rejecting a pending claim. */
    public record RejectForm(@NotBlank @Size(max = 200) String reason) {
    }

    @PostMapping("/claims/{id}/approve")
    public ClaimView approve(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9_.-]+") String sheetId,
            @PathVariable Long id, @SessionAttribute(SessionController.USER) String user) {
        return ClaimView.of(service.approve(user, sheetId, id));
    }

    @PostMapping("/claims/{id}/reject")
    public ClaimView reject(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9_.-]+") String sheetId,
            @PathVariable Long id, @Valid @RequestBody RejectForm form,
            @SessionAttribute(SessionController.USER) String user) {
        return ClaimView.of(service.reject(user, sheetId, id, form.reason()));
    }

    /** The person a claim is to move to, by id. */
    public record ReassignForm(@NotNull Long personId) {
    }

    @PostMapping("/claims/{id}/reassign")
    public ClaimView reassign(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9_.-]+") String sheetId,
            @PathVariable Long id, @Valid @RequestBody ReassignForm form,
            @SessionAttribute(SessionController.USER) String user) {
        return ClaimView.of(service.reassign(user, sheetId, id, form.personId()));
    }

    /** The date an open claim is to be deferred until. */
    public record DeferForm(@NotNull LocalDate until) {
    }

    @PostMapping("/claims/{id}/defer")
    public ClaimView defer(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9_.-]+") String sheetId,
            @PathVariable Long id, @Valid @RequestBody DeferForm form,
            @SessionAttribute(SessionController.USER) String user) {
        return ClaimView.of(service.defer(user, sheetId, id, form.until()));
    }

    @PostMapping("/claims/{id}/void")
    public ClaimView voidClaim(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9_.-]+") String sheetId,
            @PathVariable Long id, @SessionAttribute(SessionController.USER) String user) {
        return ClaimView.of(service.changeStatus(user, sheetId, id, ClaimStatus.VOID));
    }
}
package net.officefloor.hq.app.claim;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.function.Function;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import org.springframework.stereotype.Service;
import org.springframework.web.server.ResponseStatusException;

/** Status changes made to several claims together, each one on its own. */
@Service
public class ClaimBulkService {

    /** The claims a bulk action changed, in the order it took them, and how many it refused. */
    public record Result(List<Claim> changed, int refused) {
    }

    private final ClaimService claims;
    private final ClaimRepository repository;
    private final PersonRepository people;

    public ClaimBulkService(ClaimService claims, ClaimRepository repository, PersonRepository people) {
        this.claims = claims;
        this.repository = repository;
        this.people = people;
    }

    /**
     * Opens each of the claims that can be opened, in list order (the order of people, newest claim first within a
     * person), so they are numbered in that order. Each is opened in its own transaction: one that is refused, or is
     * not a claim of the sheet, is left as it is and counted as refused.
     */
    public Result open(String by, String sheetId, Set<Long> ids) {
        return each(sheetId, ids, id -> claims.changeStatus(by, sheetId, id, ClaimStatus.OPEN));
    }

    /**
     * Settles each of the claims that can be settled, in list order, by the rules of settling one claim: one the
     * clerk limit makes PENDING counts as settled. Each is settled in its own transaction: one that is refused, or is
     * not a claim of the sheet, is left as it is and counted as refused.
     */
    public Result settle(String by, String sheetId, Set<Long> ids) {
        return each(sheetId, ids, id -> claims.changeStatus(by, sheetId, id, ClaimStatus.SETTLED));
    }

    /** Applies the change to each of the sheet's claims among the ids in list order, counting the refused ones. */
    private Result each(String sheetId, Set<Long> ids, Function<Long, Claim> change) {
        Map<Long, Integer> personOrder = new HashMap<>();
        for (Person p : people.findBySheetIdOrderByIdAsc(sheetId)) {
            personOrder.put(p.getId(), personOrder.size());
        }
        List<Long> ordered = repository.findBySheetIdOrderByListedDescIdDesc(sheetId).stream()
                .filter(c -> ids.contains(c.getId()))
                .sorted(Comparator.comparing((Claim c) -> personOrder.getOrDefault(c.getPersonId(), Integer.MAX_VALUE))
                        .thenComparing(Claim::getListed, Comparator.reverseOrder())
                        .thenComparing(Claim::getId, Comparator.reverseOrder()))
                .map(Claim::getId).toList();
        List<Claim> changed = new ArrayList<>();
        int refused = ids.size() - ordered.size();
        for (Long id : ordered) {
            try {
                changed.add(change.apply(id));
            } catch (ResponseStatusException e) {
                refused++;
            }
        }
        return new Result(changed, refused);
    }
}
package net.officefloor.hq.app.claim;

import java.util.List;
import java.util.Optional;
import jakarta.persistence.LockModeType;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Lock;
import org.springframework.data.jpa.repository.Modifying;
import org.springframework.data.jpa.repository.Query;
import org.springframework.data.repository.query.Param;

public interface ClaimRepository extends JpaRepository<Claim, Long> {

    List<Claim> findBySheetIdOrderByIdDesc(String sheetId);

    /** The sheet's claims in list order: newest listed first. */
    List<Claim> findBySheetIdOrderByListedDescIdDesc(String sheetId);

    /** Gives the claim the next place in the list, so it is listed first under its person. */
    @Modifying(flushAutomatically = true)
    @Query(value = "UPDATE claim SET listed = NEXT VALUE FOR claim_listing WHERE id = :id", nativeQuery = true)
    void relist(@Param("id") Long id);

    List<Claim> findBySheetIdAndPersonIdOrderByIdDesc(String sheetId, Long personId);

    boolean existsBySheetIdAndPersonIdAndNumberAndStatus(String sheetId, Long personId, String number,
            ClaimStatus status);

    Optional<Claim> findBySheetIdAndNumber(String sheetId, String number);

    /** The last place given in the sheet's number sequence; null when none has been. */
    @Query("SELECT MAX(c.numberInSequence) FROM Claim c WHERE c.sheetId = :sheetId AND c.numberSequence = :sequence")
    Long lastInSequence(@Param("sheetId") String sheetId, @Param("sequence") String sequence);

    Optional<Claim> findByIdAndSheetId(Long id, String sheetId);

    /** The claim, locked until the transaction ends, so two status changes to it never interleave. */
    @Lock(LockModeType.PESSIMISTIC_WRITE)
    Optional<Claim> findWithLockByIdAndSheetId(Long id, String sheetId);
}
package net.officefloor.hq.app.sheet;

import jakarta.persistence.CollectionTable;
import jakarta.persistence.Column;
import jakarta.persistence.ElementCollection;
import jakarta.persistence.Entity;
import jakarta.persistence.FetchType;
import jakarta.persistence.Id;
import jakarta.persistence.JoinColumn;
import jakarta.persistence.Table;
import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.Instant;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.Optional;

/** A sheet, chosen by its id. Everything else in the app is kept per sheet. */
@Entity
@Table(name = "sheet")
public class Sheet {

    public static final String CLERK_LIMIT = "clerk-limit";
    public static final String FLOOR = "floor";
    public static final String TERMS = "terms";
    public static final String LATE_PCT = "late-pct";
    public static final String CAP = "cap";

    /** The floor, the terms and the late percent a sheet starts with, in force before any is recorded. */
    public static final BigDecimal DEFAULT_FLOOR = new BigDecimal("1.00");
    public static final int DEFAULT_TERMS = 14;
    public static final BigDecimal DEFAULT_LATE_PCT = new BigDecimal("0.00");

    @Id
    private String id;

    @Column(name = "created_at", nullable = false)
    private Instant createdAt;

    /** The sheet's own today: date decisions and default dates use it, never the real clock. */
    @Column(name = "today", nullable = false)
    private LocalDate today;

    /**
     * The values recorded for the sheet's dated settings: the clerk limit, the floor, the terms (the sheet's and each
     * grade's), the late percent and the cap, each from its from-date.
     */
    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "sheet_setting", joinColumns = @JoinColumn(name = "sheet_id"))
    private List<DatedSetting> settings = new ArrayList<>();

    /** The date claims round by: one before it rounds half up, one on or after it half to even; null for today. */
    @Column(name = "policy_date")
    private LocalDate policyDate;

    /** The date from which claims opened are numbered within their period; null (blank) for off. */
    @Column(name = "period_numbering_from")
    private LocalDate periodNumberingFrom;

    protected Sheet() {
    }

    public Sheet(String id) {
        this.id = id;
        this.createdAt = Instant.now();
        this.today = LocalDate.now();
    }

    public String getId() {
        return id;
    }

    public Instant getCreatedAt() {
        return createdAt;
    }

    public LocalDate getToday() {
        return today;
    }

    public void setToday(LocalDate today) {
        this.today = today;
    }

    /** The values recorded for the dated settings, each from its from-date. */
    public List<DatedSetting> getSettings() {
        return List.copyOf(settings);
    }

    /** Records the setting's value (null for none) from the date, replacing one already recorded from that date. */
    public void record(String key, LocalDate from, String value) {
        settings.removeIf(s -> s.getKey().equals(key) && s.getFrom().equals(from));
        settings.add(new DatedSetting(key, from, value));
    }

    /** The value recorded for the setting with the latest from-date on or before the date; empty with none. */
    private Optional<DatedSetting> inForce(String key, LocalDate on) {
        return settings.stream()
                .filter(s -> s.getKey().equals(key) && on != null && !s.getFrom().isAfter(on))
                .max(Comparator.comparing(DatedSetting::getFrom));
    }

    /** The most a clerk may settle a claim for, in force on the sheet's today; null means no limit. */
    public BigDecimal getClerkLimit() {
        return inForce(CLERK_LIMIT, today).map(DatedSetting::getValue).map(BigDecimal::new).orElse(null);
    }

    /** The least a claim's live due can be, in force on the date; the starting 1.00 before any is recorded. */
    public BigDecimal floorOn(LocalDate on) {
        return inForce(FLOOR, on).map(DatedSetting::getValue).map(BigDecimal::new).orElse(DEFAULT_FLOOR);
    }

    /** The days a claim dated on the date has to be settled in; the starting 14 before any are recorded. */
    public int termsOn(LocalDate on) {
        return inForce(TERMS, on).map(DatedSetting::getValue).map(Integer::valueOf).orElse(DEFAULT_TERMS);
    }

    /** The terms recorded for the grade in force on the date; empty when none are (the sheet's terms apply). */
    public Optional<Integer> gradeTermsOn(String grade, LocalDate on) {
        return inForce(TERMS + "-" + grade, on).map(DatedSetting::getValue).map(Integer::valueOf);
    }

    /** The terms a claim dated on the date has when its person has the grade: the grade's own, else the sheet's. */
    public int termsFor(String grade, LocalDate on) {
        return gradeTermsOn(grade, on).orElseGet(() -> termsOn(on));
    }

    /**
     * The percent of an overdue claim's figure added for every full 30 days it is overdue, in force on the claim's
     * date; the starting 0.00 before any is recorded.
     */
    public BigDecimal latePctOn(LocalDate on) {
        return inForce(LATE_PCT, on).map(DatedSetting::getValue).map(BigDecimal::new).orElse(DEFAULT_LATE_PCT);
    }

    /** The most a person's due-total can be, in force on the sheet's today; null means no cap. */
    public BigDecimal getCap() {
        return inForce(CAP, today).map(DatedSetting::getValue).map(BigDecimal::new).orElse(null);
    }

    public LocalDate getPolicyDate() {
        return policyDate;
    }

    public void setPolicyDate(LocalDate policyDate) {
        this.policyDate = policyDate;
    }

    public LocalDate getPeriodNumberingFrom() {
        return periodNumberingFrom;
    }

    public void setPeriodNumberingFrom(LocalDate periodNumberingFrom) {
        this.periodNumberingFrom = periodNumberingFrom;
    }

    /** The due-total (null for n/a, which is not capped) held to the cap when it is above it. */
    public BigDecimal capped(BigDecimal dueTotal) {
        BigDecimal cap = getCap();
        return cap != null && dueTotal != null && dueTotal.compareTo(cap) > 0 ? cap.setScale(2) : dueTotal;
    }

    /**
     * How a claim's live figures round, by the date its rounding follows: half up before the policy date (the
     * sheet's today when it is blank), half to even on or after it.
     */
    public RoundingMode roundingOn(LocalDate roundsOn) {
        LocalDate policy = policyDate != null ? policyDate : today;
        return policy != null && roundsOn.isBefore(policy) ? RoundingMode.HALF_UP : RoundingMode.HALF_EVEN;
    }
}
